  // Washington, D.C.") seeks facts, even with no wh-word and no "?".
  if ((q.match(/,/g) || []).length >= 2 && /\b[A-Z][a-z]/.test(q)) return "research";
  return /\?/.test(q) ? "research" : "chat";
}

